sed -i '/  useEffect(() => {/,/  }, \[\]);/c \  useEffect(() => {\n    const handleKeyDown = (e: KeyboardEvent) => {\n      const target = e.target as HTMLElement;\n      const isInput = target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable);\n\n      if (!isInput && e.key === " ") {\n        e.preventDefault();\n        handleTogglePlay();\n      } else if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "s") {\n        e.preventDefault();\n        projectStore.saveProject();\n      } else if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {\n        e.preventDefault();\n        setIsCommandPaletteOpen((prev) => !prev);\n      } else if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "e") {\n        e.preventDefault();\n        setIsExportModalOpen((prev) => !prev);\n      } else if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "h") {\n        e.preventDefault();\n        setIsVersionDrawerOpen((prev) => !prev);\n      } else if (!isInput && (e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "z" && !e.shiftKey) {\n        e.preventDefault();\n        projectStore.undo();\n      } else if (!isInput && (((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "z" && e.shiftKey) || ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "y"))) {\n        e.preventDefault();\n        projectStore.redo();\n      }\n    };\n    window.addEventListener("keydown", handleKeyDown);\n    return () => window.removeEventListener("keydown", handleKeyDown);\n  }, [isPlaying, currentTrack]);' src/App.tsx
